const pruneGitDeliveries = `-- name: PruneGitDeliveries :execrows
DELETE FROM git_deliveries WHERE id IN (
    SELECT x.id FROM (
        SELECT id, received_at, row_number() OVER (PARTITION BY connection_id ORDER BY id DESC) AS rn FROM git_deliveries
    ) x WHERE x.rn > 200 OR x.received_at < now() - interval '14 days')
`

// Keeps the newest 200 per connection, none older than 14 days.
func (q *Queries) PruneGitDeliveries(ctx context.Context) (int64, error) {
	result, err := q.db.Exec(ctx, pruneGitDeliveries)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const pruneGitDeliveryIDs = `-- name: PruneGitDeliveryIDs :execrows
DELETE FROM git_delivery_ids WHERE seen_at < $1
`

func (q *Queries) PruneGitDeliveryIDs(ctx context.Context, seenAt time.Time) (int64, error) {
	result, err := q.db.Exec(ctx, pruneGitDeliveryIDs, seenAt)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

